public static void check(Solution solution) {
    assert Arrays.equals(solution.maxNonDecreasingLength(new int[]{2,3,1}, new int[]{1,2,1}), 2);
    assert Arrays.equals(solution.maxNonDecreasingLength(new int[]{8,6,4,2}, new int[]{7,5,3,1}), 1);
    assert Arrays.equals(solution.maxNonDecreasingLength(new int[]{1,2,2,2,3}, new int[]{2,2,3,3,4}), 5);
    assert Arrays.equals(solution.maxNonDecreasingLength(new int[]{1000000000,1,1000000000}, new int[]{1,1000000000,1}), 3);
    assert Arrays.equals(solution.maxNonDecreasingLength(new int[]{1000000000,1000000000,1000000000}, new int[]{1000000000,1000000000,1000000000}), 3);
    assert Arrays.equals(solution.maxNonDecreasingLength(new int[]{1,3,5,7}, new int[]{2,4,6,8}), 4);
    assert Arrays.equals(solution.maxNonDecreasingLength(new int[]{1,2,3}, new int[]{3,2,1}), 3);
    assert Arrays.equals(solution.maxNonDecreasingLength(new int[]{1,3,5,7,9}, new int[]{2,4,6,8,10}), 5);
    assert Arrays.equals(solution.maxNonDecreasingLength(new int[]{3,3,3,3}, new int[]{3,3,3,3}), 4);
    assert Arrays.equals(solution.maxNonDecreasingLength(new int[]{1,2,3,4,5}, new int[]{5,4,3,2,1}), 5);
    assert Arrays.equals(solution.maxNonDecreasingLength(new int[]{8,4,6,2}, new int[]{7,3,5,1}), 2);
    assert Arrays.equals(solution.maxNonDecreasingLength(new int[]{5,3,4,5}, new int[]{1,2,3,4}), 4);
    assert Arrays.equals(solution.maxNonDecreasingLength(new int[]{1}, new int[]{2}), 1);
    assert Arrays.equals(solution.maxNonDecreasingLength(new int[]{1,1}, new int[]{2,2}), 2);
    assert Arrays.equals(solution.maxNonDecreasingLength(new int[]{5,4,3,2,1}, new int[]{1,2,3,4,5}), 5);
    assert Arrays.equals(solution.maxNonDecreasingLength(new int[]{1,3,2,1}, new int[]{2,2,3,4}), 4);
